// App code: what accepting and declining do.
import type { Example } from "../example.ts"
import { button } from "./button.ts"
import { html, type TemplateResult } from "lit-html"

export type RequestCardVariant = "surface" | "classic" | "ghost"
export type RequestCardSize = "1" | "2" | "3" | "4" | "5"

export type RequestCardProps = {
  id: string
  variant?: RequestCardVariant
  size?: RequestCardSize
  name: string
  album: string
  asked: string
  onAcceptViewer?: () => void
  onAcceptCollaborator?: () => void
  onDecline?: () => void
  class?: string
}

const variants: Record<RequestCardVariant, string> = {
  surface: "bg-subtle", // justus's grey tile
  classic: "bg-surface border border-solid border-line shadow-md",
  ghost: "bg-transparent",
}

const sizes: Record<RequestCardSize, string> = { "1": "p-2", "2": "p-3", "3": "p-4", "4": "p-5", "5": "p-6" }

/** Apps put these classes on their own request card; what the card says is app code. */
export function requestCardClass(variant: RequestCardVariant = "surface", size: RequestCardSize = "2"): string {
  return `rounded-xl ${variants[variant]} ${sizes[size]}`
}

export function requestCard(props: RequestCardProps): TemplateResult {
  const own = `flex flex-col gap-2 text-fg ${requestCardClass(props.variant, props.size)}`
  const classes = props.class === undefined ? own : `${own} ${props.class}`
  const heading = `${props.id}-title`
  return html`<article aria-labelledby=${heading} class=${classes}>
    <h2 id=${heading} class="text-base font-medium">${props.name} <span class="font-normal text-muted">wants to join “${props.album}”</span></h2>
    <p class="text-sm text-muted">${props.asked}</p>
    ${button({ label: "Accept as Viewer", variant: "primary", block: true, onClick: props.onAcceptViewer })}
    <p class="text-xs text-muted">Sees every photo, can't add any</p>
    ${button({ label: "Accept as Collaborator", variant: "default", block: true, onClick: props.onAcceptCollaborator })}
    <p class="text-xs text-muted">Sees every photo and can add their own</p>
    ${button({ label: "Decline", variant: "default", block: true, onClick: props.onDecline })}
  </article>`
}

const sample = { name: "Nils", album: "Summer 2026", asked: "Asked just now" }

export const examples: Example[] = [
  { label: "default", render: () => requestCard({ ...sample, id: "request-default" }) },
  ...(Object.keys(variants) as RequestCardVariant[]).map((variant) => ({
    label: variant,
    render: () => requestCard({ ...sample, id: `request-${variant}`, variant }),
  })),
  ...(Object.keys(sizes) as RequestCardSize[]).map((size) => ({
    label: `size ${size}`,
    render: () => requestCard({ ...sample, id: `request-size-${size}`, size }),
  })),
]
